// Generated by Claude Code on behalf of Benjamin Schwerdtner.
// Times SCI over 100k cell values (1000x100) against a plain JS loop, in a bare
// V8 context running dist/gasbb.js. The same cases run inside Apps Script via
// test/apps-script/Bench.js (scripts/gas.py bench).
import fs from "node:fs";
import path from "node:path";
import vm from "node:vm";

const root = path.dirname(new URL(import.meta.url).pathname);
const bundle = fs.readFileSync(path.join(root, "../dist/gasbb.js"), "utf8");
const ctx = { console };
vm.createContext(ctx);
vm.runInContext(bundle, ctx);
const gasbb = vm.runInContext("gasbb", ctx);

const R = 1000, C = 100;
ctx.VALUES = Array.from({length: R}, (_, i) => Array.from({length: C}, (_, j) => i * C + j));
const cases = [
  ["js: nested for loop sum", () => { let s = 0; for (const r of ctx.VALUES) for (const x of r) s += x; return s; }],
  ["sci: loop/recur + aget sum", "(let [v js/VALUES n (alength v)] (loop [i 0 s 0] (if (< i n) (let [r (aget v i) m (alength r)] (recur (inc i) (loop [j 0 s s] (if (< j m) (recur (inc j) (+ s (aget r j))) s)))) s)))"],
  ["sci: reduce over js arrays", "(reduce (fn [s r] (reduce + s r)) 0 js/VALUES)"],
  ["sci: js->clj then reduce", "(reduce (fn [s r] (reduce + s r)) 0 (js->clj js/VALUES))"],
  ["sci: mapv inc per cell", "(count (mapv (fn [r] (mapv inc r)) js/VALUES))"],
  ["sci: doseq + aset in place", "(doseq [r js/VALUES] (dotimes [j (alength r)] (aset r j (* 2 (aget r j)))))"],
];

const t = performance.now(); gasbb.evalString("1");
console.log("context init: " + (performance.now() - t).toFixed(1) + " ms");
for (const [name, c] of cases) {
  const f = typeof c === "function" ? c : () => gasbb.evalString(c);
  const t0 = performance.now(); f(); const cold = performance.now() - t0;
  const ts = [];
  for (let k = 0; k < 5; k++) { const t1 = performance.now(); f(); ts.push(performance.now() - t1); }
  ts.sort((a, b) => a - b);
  console.log(name + ": cold " + cold.toFixed(1) + " ms, warm median " + ts[2].toFixed(1) + " ms");
}
